//! Camera and lens names for the Info panel's pickers: names only, none of lensfun's correction
//! data. `data/camera-names.tsv` (lensfun's camera names merged with `docs/raw/adobe-cameras.tsv`)
//! and `data/lens-names.tsv` (lensfun's lens names and mounts) are generated by
//! `tools/camera_lens_names.py` and embedded in the binary; lensfun's database is CC-BY-SA 3.0
//! (see `assets/ATTRIBUTION.md`). The profiles in [`crate::LensDb`] are separate and are never
//! bundled.

use std::sync::OnceLock;

/// One picker row.
#[derive(Debug, Clone, PartialEq)]
pub struct Entry {
    /// The brand (`Sony`), for grouping.
    pub maker: String,
    /// The name a pick stores (`Sony ILCE-7M5`, `Sony FE 24-70mm f/2.8 GM II`).
    pub name: String,
    /// Other names the camera goes by (`A7 V`), found by search; or a lens's mounts.
    pub extra: Vec<String>,
    /// Lower-cased `name` and `extra`, what a search looks in.
    hay_name: String,
    hay_extra: String,
}

/// A list of names.
#[derive(Debug, Default)]
pub struct NameList {
    entries: Vec<Entry>,
}

/// Rows a search returns at most, unless asked for fewer.
pub const MAX_RESULTS: usize = 200;

impl NameList {
    /// Reads the TSV the generator writes: `maker`, `name`, `extra` (`;`-separated) per line; `#` lines and
    /// lines without a name are skipped.
    pub fn parse(tsv: &str) -> NameList {
        let entries = tsv
            .lines()
            .filter(|l| !l.starts_with('#'))
            .filter_map(|l| {
                let mut cols = l.split('\t');
                let (maker, name) = (cols.next()?.trim(), cols.next()?.trim());
                if name.is_empty() {
                    return None;
                }
                let extra: Vec<String> = cols.next().unwrap_or("").split(';').map(str::trim).filter(|s| !s.is_empty()).map(String::from).collect();
                Some(Entry {
                    maker: maker.to_string(),
                    name: name.to_string(),
                    hay_name: name.to_lowercase(),
                    hay_extra: extra.join("\n").to_lowercase(),
                    extra,
                })
            })
            .collect();
        NameList { entries }
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn entries(&self) -> &[Entry] {
        &self.entries
    }

    /// Rows matching `query`, best first, at most `limit`. Case-insensitive; every word of the query must appear
    /// (in the name, or in another name of the row), in any order. Ranked: the name or an alias is the query or
    /// starts with it, a word of it starts with the query, it contains the query, every word starts a word, then
    /// words spread over the name and aliases. An empty query lists the first `limit` rows.
    pub fn search(&self, query: &str, limit: usize) -> Vec<&Entry> {
        let q = query.to_lowercase();
        let q = q.split_whitespace().collect::<Vec<_>>();
        let limit = limit.min(MAX_RESULTS);
        if q.is_empty() {
            return self.entries.iter().take(limit).collect();
        }
        let whole = q.join(" ");
        let mut hits: Vec<(u8, usize, &Entry)> = self
            .entries
            .iter()
            .filter_map(|e| {
                let in_name = |t: &&str| e.hay_name.contains(t);
                let by_name = q.iter().all(in_name).then(|| {
                    if e.hay_name.starts_with(&whole) {
                        0
                    } else if word_starts(&e.hay_name, &whole) {
                        1
                    } else if e.hay_name.contains(&whole) {
                        2
                    } else if q.iter().all(|t| word_starts(&e.hay_name, t)) {
                        3
                    } else {
                        4
                    }
                });
                // one other name that is, starts with or holds the whole query
                let by_alias = e
                    .hay_extra
                    .lines()
                    .filter_map(|a| {
                        if a == whole {
                            Some(0)
                        } else if a.starts_with(&whole) {
                            Some(1)
                        } else if word_starts(a, &whole) {
                            Some(2)
                        } else {
                            a.contains(&whole).then_some(3)
                        }
                    })
                    .min();
                let spread = q.iter().all(|t| e.hay_name.contains(t) || e.hay_extra.contains(t)).then_some(5);
                let rank = [by_name, by_alias, spread].into_iter().flatten().min()?;
                Some((rank, e.name.len(), e))
            })
            .collect();
        hits.sort_by(|a, b| (a.0, a.1, &a.2.name).cmp(&(b.0, b.1, &b.2.name)));
        hits.into_iter().take(limit).map(|h| h.2).collect()
    }
}

/// Whether `needle` starts a word of `hay` (after a space, `-`, `/`, `(` or at the start).
fn word_starts(hay: &str, needle: &str) -> bool {
    hay.match_indices(needle).any(|(i, _)| hay.get(..i).and_then(|before| before.chars().next_back()).is_none_or(|c| !c.is_alphanumeric()))
}

/// The known cameras ("Sony ILCE-7M5", with aliases such as "A7 V").
pub fn cameras() -> &'static NameList {
    static LIST: OnceLock<NameList> = OnceLock::new();
    LIST.get_or_init(|| NameList::parse(include_str!("../data/camera-names.tsv")))
}

/// The known interchangeable lenses ("Sony FE 24-70mm f/2.8 GM II", with their mounts as `extra`).
pub fn lenses() -> &'static NameList {
    static LIST: OnceLock<NameList> = OnceLock::new();
    LIST.get_or_init(|| NameList::parse(include_str!("../data/lens-names.tsv")))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn names(list: &NameList, q: &str) -> Vec<String> {
        list.search(q, 10).into_iter().map(|e| e.name.clone()).collect()
    }

    #[test]
    fn the_lists_are_the_size_the_generator_makes() {
        assert!((1000..2000).contains(&lenses().len()), "{}", lenses().len());
        assert!((1800..3000).contains(&cameras().len()), "{}", cameras().len());
    }

    #[test]
    fn a_camera_is_found_by_its_code_and_its_marketing_name() {
        let c = cameras();
        assert_eq!(names(c, "ILCE-7M5").first().map(String::as_str), Some("Sony ILCE-7M5"));
        assert_eq!(names(c, "ilce-7m5").first().map(String::as_str), Some("Sony ILCE-7M5"), "case does not matter");
        assert_eq!(names(c, "A7 V").first().map(String::as_str), Some("Sony ILCE-7M5"), "the alias finds it");
        assert!(names(c, "sony a7 v").contains(&"Sony ILCE-7M5".to_string()), "{:?}", names(c, "sony a7 v"));
        assert!(names(c, "EOS R5").iter().any(|n| n.starts_with("Canon EOS R5")));
    }

    #[test]
    fn a_lens_is_found_by_part_of_its_name() {
        let l = lenses();
        let hits = names(l, "FE 24-70");
        assert!(hits.contains(&"Sony FE 24-70mm f/2.8 GM II".to_string()), "{hits:?}");
        assert!(names(l, "24-70 gm ii").contains(&"Sony FE 24-70mm f/2.8 GM II".to_string()));
        assert!(names(l, "sony fe 24").first().is_some_and(|n| n.starts_with("Sony FE 24")));
    }

    #[test]
    fn prefix_matches_come_before_substring_matches() {
        let l = NameList::parse("A\tAlpha one\t\nA\tBeta alpha\t\nA\tAlphabet soup\t\n");
        assert_eq!(names(&l, "alpha"), ["Alpha one", "Alphabet soup", "Beta alpha"]);
        assert_eq!(l.search("", 2).len(), 2, "no query lists the first rows");
        assert!(l.search("zzz", 5).is_empty());
    }

    #[test]
    fn built_in_lenses_and_placeholders_are_not_listed() {
        for l in lenses().entries().iter().chain(cameras().entries()) {
            assert!(!l.name.contains("& compatibles") && !l.name.contains("35mm film"), "{}", l.name);
            assert!(!l.maker.eq_ignore_ascii_case("generic"), "{}", l.name);
        }
        let nikon: Vec<_> = lenses().entries().iter().filter(|e| e.maker.starts_with("Nikon")).map(|e| e.maker.as_str()).collect();
        assert!(nikon.iter().all(|m| *m == "Nikon"), "maker spellings are collapsed");
        let mut seen = std::collections::HashSet::new();
        assert!(lenses().entries().iter().all(|e| seen.insert(e.name.to_lowercase())), "each lens once");
    }

    #[test]
    fn odd_input_is_harmless() {
        let l = lenses();
        for q in ["", "   ", "\u{0}", "ℵ🦀", "(", "\\", &"x".repeat(5000), "%s%s"] {
            let _ = l.search(q, 5);
        }
        assert!(NameList::parse("\t\t\n#\n\n only one column").is_empty());
        assert_eq!(l.search("a", usize::MAX).len(), MAX_RESULTS);
    }
}
